<?php defined('BASEPATH') or exit('No direct script access allowed');$c=$context;$ins=$c['installment']??['is_installment'=>false];$addr=trim(implode('، ',array_filter([$c['address']??'',$c['city']??'',$c['state']??'',$c['zip']??''])));?><!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><title>رسید تحویل کالا - فاکتور <?php echo html_escape($invoice->number);?></title><style>body{font-family:Tahoma,Arial,sans-serif;color:#111;margin:28px;direction:rtl}h1{font-size:22px;margin:0}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #111;padding-bottom:14px}.meta,.finance,.carrier{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.box{border:1px solid #bbb;border-radius:8px;padding:10px}.box small{display:block;color:#666;margin-bottom:5px}table{width:100%;border-collapse:collapse;margin-top:14px}th,td{border:1px solid #aaa;padding:8px;text-align:right}th{background:#f2f2f2}.sign{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-top:65px}.sign div{text-align:center;border-top:1px solid #333;padding-top:10px}.note{background:#f7f7f7;border:1px solid #ccc;padding:10px;margin-top:16px}.no-print{margin-bottom:18px}@media print{.no-print{display:none}body{margin:10mm}.box{break-inside:avoid}}</style></head><body><div class="no-print"><button onclick="window.print()">چاپ رسید تحویل</button> <a style="display:inline-block;margin-right:8px;padding:3px 10px;border:1px solid #999;text-decoration:none;color:#111;background:#f5f5f5" href="<?php echo admin_url('sales_delivery_flow/invoice/'.$invoice->id.'?tab=complete');?>">بازگشت به تکمیل فرآیند</a></div><div class="head"><div><h1>رسید تحویل کالا به مشتری</h1><div>فاکتور شماره <?php echo html_escape($invoice->number);?></div></div><div><b>تاریخ تحویل:</b> <?php echo html_escape($delivery['delivery_date']);?><br><b>روش تحویل:</b> <?php echo html_escape($delivery['delivery_method']?:'-');?></div></div><div class="meta"><div class="box"><small>مشتری</small><b><?php echo html_escape($c['company']??'-');?></b></div><div class="box"><small>شماره تماس</small><b><?php echo html_escape($c['phonenumber']??'-');?></b></div><div class="box"><small>تاریخ فاکتور</small><b><?php echo html_escape($c['display_date']??$invoice->date);?></b></div></div><div class="box"><small>نشانی تحویل</small><b><?php echo html_escape($addr?:'-');?></b></div><h3>اقلام تحویلی</h3><table><thead><tr><th>ردیف</th><th>شرح کالا</th><th>تعداد</th><th>قیمت واحد</th><th>تخفیف</th><th>مبلغ ردیف</th></tr></thead><tbody><?php foreach(($c['items']??[]) as $k=>$it){?><tr><td><?php echo $k+1;?></td><td><?php echo html_escape($it['description']??'');?></td><td><?php echo html_escape($it['qty']??'');?></td><td><?php echo app_format_money($it['rate']??0,'');?></td><td><?php echo !empty($it['discount_amount_value'])?app_format_money($it['discount_amount_value'],''):'—';?></td><td><?php echo app_format_money($it['line_total']??0,'');?></td></tr><?php }?></tbody></table><h3>وضعیت تسویه حساب</h3><div class="finance"><div class="box"><small>مبلغ کل فاکتور</small><b><?php echo app_format_money($c['total']??0,'');?></b></div><div class="box"><small>پرداخت‌شده</small><b><?php echo app_format_money($c['paid']??0,'');?></b></div><div class="box"><small>مانده</small><b><?php echo app_format_money($c['remaining']??0,'');?></b><br><?php echo html_escape($c['payment_state']??'');?></div></div><?php if(!empty($ins['is_installment'])){?><div class="note"><b>تسویه اقساطی:</b> <?php echo html_escape($ins['title']);?> | پیش‌پرداخت: <?php echo app_format_money($ins['down_payment'],'');?> | تعداد اقساط: <?php echo (int)$ins['installment_count'];?> | پرداخت‌شده: <?php echo (int)$ins['paid_installment_count'];?> قسط</div><?php }?><?php if(!empty($delivery['carrier_company'])||!empty($delivery['carrier_driver'])||!empty($delivery['carrier_tracking'])){?><h3>اطلاعات شرکت باربری / حمل</h3><div class="carrier"><div class="box"><small>شرکت باربری</small><b><?php echo html_escape($delivery['carrier_company']?:'-');?></b></div><div class="box"><small>راننده / نماینده</small><b><?php echo html_escape($delivery['carrier_driver']?:'-');?></b></div><div class="box"><small>تماس باربری</small><b><?php echo html_escape($delivery['carrier_contact']?:'-');?></b></div><div class="box"><small>خودرو / پلاک</small><b><?php echo html_escape($delivery['carrier_vehicle']?:'-');?></b></div><div class="box"><small>بارنامه / رهگیری</small><b><?php echo html_escape($delivery['carrier_tracking']?:'-');?></b></div></div><?php }?><div class="note"><b>تحویل‌گیرنده:</b> <?php echo html_escape($delivery['recipient_name']?:'-');?> | <b>تماس:</b> <?php echo html_escape($delivery['recipient_phone']?:'-');?><br><?php echo nl2br(html_escape($delivery['note']??''));?></div><div class="sign"><div>امضاء مدیر نمایشگاه</div><div>امضاء حسابدار</div><div>امضاء شرکت باربری / راننده<br><small>در صورت وجود</small></div><div>امضاء مشتری / تحویل‌گیرنده</div></div></body></html>
